                malformed = fault
            elseif length < 0 then
                malformed = "length " .. length .. " is negative"
            elseif length < header then
                malformed = "length " .. length .. " is below the " .. header .. "-byte header"
            end
            if malformed then
                dissect_message(tvb(offset):tvb(), pinfo, tree, malformed)
                return total
            end
